import type { Passage } from '../../core/story-types';

/** In source order: each stretch's table, then the 'Anywhere' four, then the 40 extra lines. Shown in order within a stretch. */
export const passages: Passage[] = [
  { id: "ps-m01", stretch: "st-mouth", req: [], line: "The rungs are cold beneath your hands, colder than the air around them, and the chill passes quickly into your palms. Each takes your weight with a small hard certainty until the ninth shifts loose in its bracket. It moves only a little, but enough for your grip to tighten and your boots to pause on the rung below." },
  { id: "ps-m02", stretch: "st-mouth", req: [], line: "Looking up the shaft, the ladder rails draw together towards the daylight until the space between them seems scarcely wider than a hand. The brightness above whitens their upper edges and leaves the lower lengths dark. Your eye follows the narrowing pair upward, rung after rung, until the ladder appears to end inside the pale opening itself." },
  { id: "ps-m03", stretch: "st-mouth", req: [], line: "A steady draught passes your face on its way up the shaft, cool enough to dry the damp at your temples. It keeps the same direction and pressure, brushing your cheeks before climbing past the ladder. You breathe through your nose and find no mineral tang, no dust, no dampness in it. It smells of nothing." },
  { id: "ps-m04", stretch: "st-mouth", req: [], until: "seal-1-5", line: "At the ladder’s foot, a recess is cut into the shaft wall, shallow enough that its back remains plainly visible. Strokes run along its lip in a close line, their grooves dark against the worn edge. A nail is fixed above it, standing from the wall by itself. The metal and the cut recess make a small, deliberate arrangement beside the ladder." },
  { id: "ps-m05", stretch: "st-mouth", req: [], line: "The passage bends left by such a slow degree that the turn is almost invisible. No single place can be called the corner; instead, the left wall keeps drawing inward by fractions while the right eases away. Only after several strides do you notice that the shaft is no longer behind you in a straight line." },
  { id: "ps-m06", stretch: "st-mouth", req: [], line: "The passage floor is furred with dust finer than flour. Your boots sink through the topmost layer without resistance, raising pale clouds that billow no higher than your ankles. Each step leaves a dark-edged print for a moment before loosened dust drifts back across it. Behind you, the stirred powder settles slowly into the shallow hollows of the floor." },
  { id: "ps-m07", stretch: "st-mouth", req: [], line: "The walls are so smooth that dust finds nowhere to cling. What settles there slips down in faint vertical traces and gathers instead along the floor. Under your hand the stone offers no ridge broad enough to hold grit, only a continuous hard plane. Even the finest powder seems temporary on it, leaving the wall bare again." },
  { id: "ps-m08", stretch: "st-mouth", req: [], line: "A cable bracket is bolted to the shaft brick, its two fastenings sunk deep into the mortar line. The bracket projects just far enough to show the curve where something once rested. The cable itself is gone. Empty metal holds empty air, with a narrow clean shadow beneath it where the brick face turns away." },
  { id: "ps-m09", stretch: "st-mouth", req: [], line: "Wear has hollowed the middle of the passage floor by a hand’s depth. The depression runs lengthwise, broad and smooth, while the margins beside the walls remain higher. Your boots naturally fall into the worn centre. From there the floor rises gently to either side, the stone thinned by use into a long shallow channel." },
  { id: "ps-m10", stretch: "st-mouth", req: [], line: "From here, the only sound is air moving up the shaft behind you. It is not a whistle or a gust, but a continuous low passage of air, soft against the brick throat. Your own steps interrupt it briefly; when you stop, the draught remains, a single unbroken sound receding upward towards the daylight." },
  { id: "ps-h01", stretch: "st-hall", req: [], until: "b-3.A", line: "The hall goes on past where the light of the lamp on the ledge reaches, and the air is colder that way." },
  { id: "ps-h02", stretch: "st-hall", req: [], until: "b-3.A", line: "At head height, an empty cup is cut into the wall. Its hollow is smooth enough to catch a crescent of lamplight along the rim, while the centre stays dark. The flame’s mark is cut inside it, contained entirely by the cup, its grooves following the same stone that forms the shallow bowl." },
  { id: "ps-h03", stretch: "st-hall", req: [], until: "b-3.A", line: "Another cup follows, then another, each a few paces from the last. Their spacing repeats down the wall with an almost bodily rhythm: walk, cup; walk, cup. Every hollow is empty. The rims catch the lamp in turn, but nothing sits inside any of them to interrupt the bare stone." },
  { id: "ps-h04", stretch: "st-hall", req: [], line: "Dozens of rings cover the wall at shoulder height. Some nearly meet; others sit apart in small islands of untouched stone. Their edges have been softened by wear, so that a fingertip would find rounded grooves rather than fresh-cut corners. Together they make a dense band across the wall without becoming one continuous pattern." },
  { id: "ps-h05", stretch: "st-hall", req: [], until: "b-3.A", line: "The floor is one stone as far as the lamp on the ledge shows, with no joins in it." },
  { id: "ps-h06", stretch: "st-hall", req: [], until: "b-3.A", line: "From this far down the hall, the lamp on its ledge is small. Its flame has narrowed to a steady point of colour against the dark wall behind it. It does not flicker. Even at this distance the flame keeps its shape, while the stone around it has already lost most of its detail." },
  { id: "ps-h07", stretch: "st-hall", req: [], until: "b-3.A", line: "The ceiling curves over so high that the light of the lamp on the ledge gives out before it reaches it." },
  { id: "ps-h08", stretch: "st-hall", req: [], line: "The marks continue above the height of your reach. You lift a hand towards the higher cuts and still fall short, the uppermost grooves remaining well beyond your fingertips. Their continuation changes the scale of the worked wall; what seemed a band at eye level proves to climb into a part of the stone you cannot touch." },
  { id: "ps-h09", stretch: "st-hall", req: [], until: "b-3.A", line: "The lintel stands on the side wall, its straight upper stone framing a place that is not open. Beneath it is solid stone, continuous with the wall around it. Beside its two marks is a blank: a clean portion of surface left uncut, conspicuous only because the worked stone presses so closely around it." },
  { id: "ps-h10", stretch: "st-hall", req: [], until: "b-3.A", line: "At the far end the light of the lamp on the ledge stops well short of the door." },
  { id: "ps-h11", stretch: "st-hall", req: [], line: "The hall smells of dry stone, a thin mineral scent that seems to belong to the dustless walls themselves. Beneath it is salt, faint but distinct when you draw a slower breath. The two smells remain separate: stone first, dry and plain; then the slight saline edge underneath, as if the air has crossed another chamber before reaching you." },
  { id: "ps-h12", stretch: "st-hall", req: ["b-3.A"], line: "Flames burn in the cups along both walls, each exactly the height of the next. They face one another across the hall in level rows, neither side rising nor dipping. The repeated points of fire make the scale of the walls suddenly legible, their equal height running away into distance with almost mathematical steadiness." },
  { id: "ps-h13", stretch: "st-hall", req: ["b-3.A"], line: "Lamplight puts a small shadow into every cut on the walls. The deepest grooves hold the darkest slivers, while shallower incisions carry only a thin edge of shade. Across the worked surface, thousands of little dark lines appear inside the stone itself, each one tied exactly to the depth and angle of a cut." },
  { id: "ps-h14", stretch: "st-hall", req: ["b-3.A"], line: "The lamps continue round the corner towards the salt. One after another, their flames turn out of sight, the nearest bright and the farther ones reduced to narrow glows along the bend. Their sequence makes the corner visible before the wall itself is clear, leading the eye from worked stone towards the paler reach beyond." },
  { id: "ps-h15", stretch: "st-hall", req: ["b-3.A"], line: "Each wall-cup casts a small half-moon of light onto the floor. The bright curves repeat at regular intervals, one after another, each opening towards the hall in the same way. Between them lie strips of dim stone. From where you stand, the floor looks lightly scalloped by illumination, a chain of pale crescents laid beside the walls." },
  { id: "ps-h16", stretch: "st-hall", req: ["b-3.A"], line: "The stone below the lintel is gone. Where there was once an unbroken wall, an opening now cuts through beneath the horizontal stone. Beyond it, the landing is already lit. Its light reaches the threshold from the other side, so the rectangular opening appears not as a black absence but as a brighter interruption in the wall." },
  { id: "ps-h17", stretch: "st-hall", req: ["b-3.A"], until: "b-7.C", line: "The flames stand straight even while the draught passes along the hall. You can feel the moving air against your skin, yet each narrow flame rises vertically from its cup without leaning. The contrast is precise enough to notice from several paces away: air in motion, fire apparently untouched by it." },
  { id: "ps-h18", stretch: "st-hall", req: ["b-3.A"], line: "With the hall lit, a paler track appears worn down the centre of the floor. It runs between the rows of lamps, broad enough for a steady line of feet, its surface rubbed lighter than the stone to either side. The track is not sharply edged; it fades gradually into the unworn floor as the abrasion thins." },
  { id: "ps-h19", stretch: "st-hall", req: ["b-3.A"], line: "The great door takes up the wall at the far end, occupying so much of it that little stone remains visible around the edges. The lamps stop before reaching it. Their final flames leave a stretch of dim floor between the last cup and the door, so the great surface stands partly outside the ordered light of the hall." },
  { id: "ps-h20", stretch: "st-hall", req: ["b-3.A"], line: "Now the light reaches the ceiling. Marks are cut there too, spread across the curved stone above you, with rings among them. Seen overhead, the grooves catch light differently from those on the walls: their lower edges brighten while the cuts themselves darken, carrying the worked surface across the roof of the hall." },
  { id: "ps-h21", stretch: "st-hall", req: ["b-3.A"], line: "Every wall-cup burns with the same coloured flame as the clay lamp. From cup to cup the hue does not vary, even where the stone around them changes in brightness. None contains oil. Inside each shallow hollow there is only the flame and bare stone, no dark pool or wick visible beneath the fire." },
  { id: "ps-h22", stretch: "st-hall", req: [], line: "The ledge is part of the wall itself, cut from the same stone without a join. Its underside flows directly into the vertical face; the top has no fitted seam or change of grain. Running your eye along the edge reveals no inserted slab, only one mass of stone worked outward into a narrow shelf." },
  { id: "ps-c01", stretch: "st-salt", req: [], line: "At the corner, two smooth troughs dip into the floor a stride apart. Each is hollowed like a basin, broad enough for the curve to be obvious beneath your boots. Their interiors are smoother than the surrounding stone, and both descend gently before rising again, twin depressions placed side by side across the turn." },
  { id: "ps-c02", stretch: "st-salt", req: [], line: "The polished patch at the corner catches the light with a muted gleam. Its surface is worn smooth enough to return the lamp in a soft blur, while the rest of the wall stays matt and swallows the same light. The boundary is irregular but plain, a brightened island of handling or wear against dull stone." },
  { id: "ps-c03", stretch: "st-salt", req: [], line: "Beyond the turn, the smell of salt strengthens. It arrives before the salt face fills your view, dry and mineral on the back of your tongue. The farther you round the bend, the less the hall smells merely of stone; the sharper saline note gathers in the air until it becomes the dominant thing you breathe." },
  { id: "ps-c04", stretch: "st-salt", req: [], line: "Here the floor itself is salt, packed hard and grey beneath your boots. It does not crumble under an ordinary step, but it gives a faint creak as your weight passes over it. The surface is rougher than the stone behind you, granular at the edges and compressed smooth along the places most often crossed." },
  { id: "ps-c05", stretch: "st-salt", req: [], line: "Grey and white bands run through the salt face. They are not painted on the surface but belong to the material itself, one layer passing into the next with uneven borders. Some are thin as a finger; others spread wider. The alternating colours make the wall appear built in long horizontal changes, though the salt remains continuous." },
  { id: "ps-c06", stretch: "st-salt", req: [], line: "The tally follows the wall at about the height of a man’s chest. Its cuts hold a steady level even where the salt and stone around them vary. You can walk beside it without lifting or lowering your gaze much, the line of marks travelling parallel to your shoulders along the length of the gallery." },
  { id: "ps-c07", stretch: "st-salt", req: [], line: "White salt has furred the lowest cuts of the tally. Crystals crowd into the grooves and soften their lower edges, bright against the darker material beneath. The higher cuts remain clearer. Where the crust is thickest, the original incision can be followed only by the slight trench it leaves through the granular white growth." },
  { id: "ps-c08", stretch: "st-salt", req: [], line: "Her sheets remain tucked in the crack, held where the stone pinches them. The top one has begun to curl at a corner, lifting away from the stack in a dry arc. Its edge casts a thin shadow on the page beneath, while the rest of the papers stay pressed flat inside the narrow opening." },
  { id: "ps-c09", stretch: "st-salt", req: [], line: "The split has been packed tight: stone against stone, every gap worked full of salt. Small fragments wedge between larger pieces until there is scarcely a dark space left. The white packing fills the irregular seams around them, making the whole repair look dense and compressed rather than loose, as though the split has been patiently stuffed from edge to edge." },
  { id: "ps-c10", stretch: "st-salt", req: ["seal-1-1"], line: "Small pictures interrupt the tally’s marks: a lamb, a loaf, a long-legged bird. Each appears among the cuts without changing the tally’s level along the wall. The figures are simple enough to read at once, yet distinct from the strokes around them, brief recognisable shapes set into the same worked surface." },
  { id: "ps-c11", stretch: "st-salt", req: [], line: "The roof is low enough to feel close above your head. You do not need to reach far to judge the distance. The salt overhead has a dull sheen, not bright enough to reflect the lamps clearly, but sufficient to show shallow changes in its surface whenever you tilt your face upward." },
  { id: "ps-c12", stretch: "st-salt", req: [], line: "Where cut stone meets salt, the boundary is straight as a rule. There is no ragged transition between the two materials: one ends and the other begins along a clean, unwavering line. The different colours and textures make the division sharper still, worked stone on one side, granular salt on the other." },
  { id: "ps-c13", stretch: "st-salt", req: [], line: "Fine salt dust has drifted against the wall, granular as sugar. It lies deepest where the floor meets the vertical face, thinning outward into scattered grains. When your boot passes close, a few crystals roll down the small slope and catch briefly in the lamplight before settling among the rest." },
  { id: "ps-c14", stretch: "st-salt", req: [], line: "Short, slanting pick-scars score the salt face. Each cut is only a little longer than a finger joint, but together they cover a broad patch in repeated diagonal strokes. Their lower lips hold pale dust; their upper edges stay sharper, so the wall seems combed in one direction by many separate blows." },
  { id: "ps-c15", stretch: "st-salt", req: ["b-4.A"], line: "The tally disappears beneath a crust of salt and emerges again on the far side. For a short stretch the marks are completely buried, the white mineral growth crossing them without a break. Then the cuts return at the same height and spacing, continuing beyond the crust as though the interruption were laid over an unbroken line." }, // NOTE: from w4 in the source; req b-4.A (the crust first seen) stands in
  { id: "ps-c16", stretch: "st-salt", req: [], line: "Beyond the split, the gallery narrows until a man with both arms out could span it. The walls draw close enough that their distance can be judged by your shoulders rather than by sight. The tighter width changes the air around you too, concentrating the dry salt smell between two near faces of stone and mineral." },
  { id: "ps-c17", stretch: "st-salt", req: [], line: "Every so often the salt gives a small tick, like a stove cooling. The sound is brief and hard, gone before you can turn towards it. Then there is quiet again until another tick comes from somewhere in the salt, not loud enough to echo, only a tiny dry contraction inside the gallery." },
  { id: "ps-c18", stretch: "st-salt", req: ["b-3.A"], line: "Light from the corner brings out the bands in the salt all the way to the top of the face. Pale stripes broaden and narrow as they rise, with darker grey between them. The illumination reaches high enough that the layering can be followed without interruption from near the floor to the upper edge of the visible wall." },
  { id: "ps-c19", stretch: "st-salt", req: ["b-2.A"], line: "The lone ring above the tally takes the light before the cuts around it do. Its upper curve brightens first, forming a clear arc while neighbouring marks remain subdued. As you alter your position, the ring keeps catching the lamp on its rounded edge, standing apart from the shallower, straighter incisions below." },
  { id: "ps-c20", stretch: "st-salt", req: [], line: "A hollow has been worn into the floor in front of the tally, where someone stood to read. It is broad enough for two feet and deepest at its centre, with the salt or stone smoothed by repeated weight. Standing there places your chest almost level with the marks, the worn depression fitting naturally beneath your boots." },
  { id: "ps-s01", stretch: "st-camp", req: [], line: "Her camp smells of paraffin and paper. The paraffin is the stronger note, oily and faintly sharp, but underneath it sits the dry, fibrous smell of stacked sheets and notebooks. The mixture belongs to this small chamber alone; near the doorway, the scent thins quickly into the mineral air outside." },
  { id: "ps-s02", stretch: "st-camp", req: [], line: "The cot canvas has sagged into the shape of the person who slept there. A shallow trough runs from shoulders to hips, with deeper give near the middle where the fabric has stretched most. The canvas is still under tension at the edges, so the depression keeps its human length even without anyone lying in it." },
  { id: "ps-s03", stretch: "st-camp", req: [], line: "One bootlace trails from beneath the cot, untied at the end. Only part of the boot is visible in the shadow, but the lace reaches out across the floor in a loose curve. Its final few inches have separated into two stiffened tips, resting where they fell without a knot to gather them." },
  { id: "ps-s04", stretch: "st-camp", req: [], line: "A single nail remains in the wall above the cot. It stands at a slight upward angle, its head dark against the stone. Nothing hangs from it. The bare patch around the nail is small and plain, and the empty space beneath it reaches all the way down to the rumpled edge of the cot." },
  { id: "ps-s05", stretch: "st-camp", req: [], line: "Pencilled sums cover the wall by the doorway, crossed through one after another. Numbers sit in short columns and uneven rows, each abandoned calculation struck through before the next begins. The graphite varies from dark to faint where the pencil pressure changed, turning this narrow strip of wall into a worked surface of arithmetic rather than carving." },
  { id: "ps-s06", stretch: "st-camp", req: [], line: "Tooth marks run the length of the notebook’s pencil. They begin near the sharpened end and continue almost to the blunt paint above the ferrule, overlapping in small paired dents. Some bites have broken the lacquer; others merely press it inward. Rolled between your fingers, the pencil feels ridged where the teeth have roughened its once-smooth sides." },
  { id: "ps-s07", stretch: "st-camp", req: [], line: "The chamber has the hall’s rounded shape, but here the ceiling is low enough to touch. Raising your arm brings your palm to the curve without fully straightening the elbow. That same arch which felt lofty outside is compressed here into a close roof, enclosing the camp in a smaller version of the hall’s form." },
  { id: "ps-s08", stretch: "st-camp", req: [], line: "A folding chair stands against the wall, one leg bound with tape. The wrapping circles the metal several times, wrinkled where one layer crosses another. That leg sits a fraction thicker than the rest and meets the floor with the tape still in place, while the chair’s folded joints and canvas seat remain otherwise ordinary." },
  { id: "ps-s09", stretch: "st-camp", req: ["b-2.B"], line: "Dust covers the shelf except for one clean forearm-long stripe. The cleared patch is sharply different from the grey powder around it, exposing the darker shelf beneath. Its length and narrowness make it conspicuous: a single horizontal absence in the dust, beginning near one end and stopping before the other." },
  { id: "ps-s10", stretch: "st-camp", req: [], line: "A pair of socks hangs from a string across the corner, dried stiff as card. They do not sag around the line so much as hold their own flattened shapes, toes pointing down at slightly different angles. Their fabric looks rough and rigid, each crease fixed where it dried rather than folding under its own weight." },
  { id: "ps-s11", stretch: "st-camp", req: [], line: "Her belongings are stacked along the wall in squared-off piles. The stacks keep their edges surprisingly straight against the curved stone, with one pile ending where the next begins. Nothing projects far into the chamber. The arrangement uses the narrow strip beside the wall closely, leaving the rest of the floor comparatively open." },
  { id: "ps-s12", stretch: "st-camp", req: [], line: "An upturned plastic crate serves as a table, its open sides now facing the floor. The top is marked by rings from mugs: overlapping circles, some dark and complete, others broken where only part of a wet base touched. The crate bows slightly beneath them, its moulded grid visible under the stains." },
  { id: "ps-t01", stretch: "st-stair", req: [], line: "The landing has no rail along its edge. The stone simply ends, leaving the drop exposed beside your feet. The first step is a stride below it, lower than an ordinary stair and deep enough that you test the distance before committing your weight. The open edge makes that first descent feel broader than the stair itself." },
  { id: "ps-t02", stretch: "st-stair", req: [], line: "The treads are so deep that you could lie down on one without your shoulders or heels crossing either edge. Each step is less a narrow place for a foot than a shallow terrace of stone. Descending means crossing a breadth of level surface before reaching the next drop." },
  { id: "ps-t03", stretch: "st-stair", req: [], line: "Use has worn the middle of each step pale. The lighter strip repeats from tread to tread, broadest where feet have passed most often and fading towards the edges. Your own boots fall naturally into that bleached centre, following a route made visible by abrasion rather than by any painted or cut guide." },
  { id: "ps-t04", stretch: "st-stair", req: [], line: "The rail is cut from the wall itself and reaches your chest. It projects as one continuous ridge of stone, thick enough to take your palm without feeling delicate. There is no bracket beneath it and no joint where another material begins; the wall simply swells outward into a long hand-height ledge." },
  { id: "ps-t05", stretch: "st-stair", req: [], line: "The stair lamps descend ahead, one every few steps. Their flames mark the drop in measured intervals, each lower than the one before. Between them the treads darken, then brighten again around the next cup, so the Stair reveals its depth in a descending sequence of small pools of light." },
  { id: "ps-t06", stretch: "st-stair", req: ["b-4.1"], line: "After the first turn, the hall’s light is behind you. It remains visible above the bend for a short distance, then the stone cuts it off. The Stair’s own lamps continue below, each flame taking over from the lost brightness overhead and carrying the descent into a separate, lower chain of illumination." }, // NOTE: from w4 in the source; req b-4.1 (down to the first turn) stands in
  { id: "ps-t07", stretch: "st-stair", req: [], line: "Rings are cut into the Stair wall too, at the eye-height of a tall man. From where you stand they sit above your own level of vision, forcing you to tilt your head slightly to follow them. Their height remains consistent as the steps fall, descending with the Stair rather than holding level with the hall." },
  { id: "ps-t08", stretch: "st-stair", req: [], line: "Air rises slowly up the Stair, a little warmer than the hall behind you. The difference is slight but steady, touching your face from below and passing upward along the flights. The deeper steps therefore send warmth rather than cold towards you, enough to make the upper hall feel comparatively cool when you glance back." },
  { id: "ps-t09", stretch: "st-stair", req: [], line: "A chip is missing from one step. The piece still lies on the tread below, its broken face matching the pale wound above in colour and grain. It has fallen only the height of a single riser and come to rest there, close enough that the missing corner and the detached fragment can be seen together." },
  { id: "ps-t10", stretch: "st-stair", req: [], line: "Marks cover the Stair walls above and beyond the lamps. Some disappear into darkness higher up, while others continue down past each pool of flame. The worked surface therefore exceeds the part properly lit for walking; wherever the light reaches sideways, more cuts become visible beyond the neat line of the lamp cups." },
  { id: "ps-t11", stretch: "st-stair", req: [], line: "Seen from the landing, the top flight appears shorter than it is. The broad treads compress one behind another when viewed from above, hiding much of their depth. Once you begin descending, each step proves long enough to cross in several paces, and the foreshortened flight unfolds into more distance than the landing suggested." },
  { id: "ps-t12", stretch: "st-stair", req: [], until: "seal-4-1", line: "At the first turn, beside the rail, a niche waits with an empty count. The recess is plainly set apart from the surrounding wall, but there are no marks occupying the place prepared for them. Its blank interior catches the nearby lamp evenly, making the absence inside it more visible than a shadowed hollow would be." },
  { id: "ps-t13", stretch: "st-stair", req: [], line: "The top of the rail is polished darker than the wall around it. Repeated contact has smoothed the stone until it reflects a subdued sheen, while the vertical face below remains lighter and rougher. Your palm fits the worn band exactly, covering the same narrow strip that carries the darker polish down the flight." },
  { id: "ps-t14", stretch: "st-stair", req: ["b-4.1"], line: "The stair lamps throw light onto the underside of the flight above. Instead of disappearing into blackness, the stone over your head is washed by a low amber glow, strongest near each flame. The undersurface reveals its curve and weight from below, turning the flight overhead into a lit ceiling for part of the descent." }, // NOTE: from w4 in the source; req b-4.1 stands in
  { id: "ps-t15", stretch: "st-stair", req: [], line: "Grit crunches beneath your boot on one step, a brief scatter of hard grains that shifts under your sole. The next has been swept clean. Its surface shows the worn stone without loose particles, making the difference between the two treads immediate through both sound and footing." },
  { id: "ps-t16", stretch: "st-stair", req: [], line: "At the first turn, the wall swells around the rail like a knuckle. The smooth ridge thickens where the direction changes, bulging outward before narrowing again along the next flight. Your hand has to follow that rounded mass through the corner rather than tracing a sharp angle." },
  { id: "ps-t17", stretch: "st-stair", req: [], line: "Two lamps stand at the turn, one on each side, like gateposts. Their flames face one another across the width of the landing, equal in height and brightness. Passing between them briefly lights both sides of you at once before the next flight takes you below their level." },
  { id: "ps-t18", stretch: "st-stair", req: [], until: "b-4.1", line: "From the first turn the second flight falls away, with a small door set into it. The door interrupts the descending wall at a lower level, compact against the scale of the Stair. Its position becomes clearer from the turn, where the angle lets you see both the next run of steps and the opening built into its side." },
  { id: "ps-t19", stretch: "st-stair", req: [], line: "A long hand could lie along this rail without bending at the wrist. The top surface is broad and level enough to support palm, fingers and thumb in one plane. When your own hand rests there, stone extends beyond it on both sides, making the rail feel more like a narrow shelf than a rounded bar." },
  { id: "ps-t20", stretch: "st-stair", req: [], line: "There are no joins between the steps. The entire flight is one piece of stone, riser flowing into tread and tread into riser without seams. Even at the corners, where fitted blocks might be expected, the grain continues uninterrupted. The Stair has been cut into a single mass rather than assembled from separate slabs." },
  { id: "ps-f01", stretch: "st-flight2", req: [], line: "The second flight falls more steeply than the first. The drop from tread to tread is greater, so each descent takes more of your weight before the next broad surface meets your boot. Looking down, the steps stack more tightly against one another, and the lower landing appears beneath a sharper angle of stone." },
  { id: "ps-f02", stretch: "st-flight2", req: [], line: "A finger’s width of darkness shows along one edge of the little door. The gap is narrow but continuous, a black seam between the door and its frame. Elsewhere the edges sit close against the stone, which makes this single dark margin conspicuous whenever the nearby lamp reaches it." },
  { id: "ps-f03", stretch: "st-flight2", req: [], until: "seal-5-1", line: "Beneath the second turn is the recess with its count. It sits tucked under the change of direction, low enough that the upper flight forms part of the space above it. The count occupies the recess plainly, its marks contained within the cut-out area rather than spreading onto the surrounding Stair wall." },
  { id: "ps-f04", stretch: "st-flight2", req: [], line: "The lamps on the second flight stand farther apart. More dark stone lies between one flame and the next, and each pool of light has faded before the following one begins. The intervals make the lower flight feel less evenly illuminated, with longer stretches of tread and wall carried only by the nearest distant glow." },
  { id: "ps-f05", stretch: "st-flight2", req: [], line: "At the second turn, the stone pales almost to cream. The change is gradual across several feet, darker grey giving way to a warm, chalky colour at the landing. The lamps make the pale section appear brighter still, but the difference remains visible even where their light weakens along the adjoining flight." },
  { id: "ps-f06", stretch: "st-flight2", req: ["b-5.B"], line: "At the gap, the rounded stone has been hacked back rough with smaller tools. The otherwise smooth curve breaks into short facets and uneven bites, each removal exposing a fresh angular face. The roughened area is confined to the gap, so the contrast with the original rounded working is abrupt beneath your hand." },
  { id: "ps-f07", stretch: "st-flight2", req: ["pl-w5-second-landing"], line: "Wear curves across the second landing’s floor towards the low doorway. The rubbed track enters from the descending flight, bends over the landing, and aims directly at the opening. Its pale surface broadens slightly at the turn, as though feet changed direction there before narrowing again at the threshold." }, // NOTE: from w5 in the source; req pl-w5-second-landing stands in
  { id: "ps-f08", stretch: "st-flight2", req: ["pl-w5-second-landing"], line: "The lamps on the second landing sit lower in the wall than those on the Stair. Their cups are nearer your waist than your hand, bringing the flames down towards the floor. The lowered light throws longer upward shadows from small irregularities in the stone and leaves the upper part of the landing comparatively dim." },
  { id: "ps-f09", stretch: "st-flight2", req: [], line: "Here the rings are smaller and more closely packed. Their curves nearly crowd one another, leaving narrow bridges of untouched stone between neighbouring cuts. A hand could cover several at once. The denser pattern makes this section of wall look more finely worked than the broader rings seen higher on the Stair." },
  { id: "ps-f10", stretch: "st-flight2", req: [], line: "A ring is cut into the riser of one step, too low for anyone standing to read. It faces outward just above the tread below, close to ankle height. To see the whole circle squarely you have to lower your gaze towards the stone between your boots, where its groove sits partly in shadow." },
  { id: "ps-f11", stretch: "st-flight2", req: ["b-6.A"], line: "Below the second landing, the Stair continues. A lintel spans it, straight across the descending space, with nothing but stone underneath. No opening interrupts the wall beneath that horizontal member. From the landing, lintel and solid stone sit together as an architectural shape without a passage through it." }, // NOTE: from w6 in the source; req b-6.A (the week 6 opener) stands in
  { id: "ps-f12", stretch: "st-flight2", req: [], line: "For one stride, the rail on the second flight is broken away. The gap exposes the wall where the handhold should continue, then the rail resumes beyond it. The old break has worn smooth: no fresh splinters of stone remain, only rounded edges at both ends where the missing section begins and stops." },
  { id: "ps-f13", stretch: "st-flight2", req: ["pl-w5-second-landing"], line: "From the second landing, you can hear air moving somewhere far below. The sound is faint and broad rather than local, rising through the lower Stair without revealing a single source. It comes and goes slightly with the shape of the descent, but always from beneath you, beyond the lamps presently in view." }, // NOTE: from w5 in the source; req pl-w5-second-landing stands in
  { id: "ps-f14", stretch: "st-flight2", req: ["pl-w5-second-landing"], line: "A small square stone lies on the landing. It is not made from the Stair’s stone: its colour and grain differ plainly from the pale surface beneath it. Someone carried it here. The piece is compact enough to lift in one hand, its four sides unusually regular against the worn curves of the landing." }, // NOTE: from w5 in the source; req pl-w5-second-landing stands in
  { id: "ps-f15", stretch: "st-flight2", req: ["pl-w5-second-landing"], line: "The lamps on the landing throw your shadow back up the Stair. It climbs across the risers behind you, lengthening over each change in level until the head reaches farther up the flight. When you move, the stepped surface breaks the outline into offsets, but the whole shadow still points upward towards the turn." }, // NOTE: from w5 in the source; req pl-w5-second-landing stands in
  { id: "ps-f16", stretch: "st-flight2", req: [], line: "The second flight’s steps rise as high as those above, but their treads are narrower. Your foot meets the same vertical climb at each riser, yet there is less level stone before the next drop. The altered proportions make the lower flight feel steeper underfoot even where the height of each individual step has not changed." },
  { id: "ps-g01", stretch: "st-square", req: [], line: "The square gallery runs dead straight, as though laid out with a rule. Its walls neither bow nor wander, and the floor keeps the same course beneath them. Looking ahead, the two sides diminish towards a single dark centre, their rigid parallel lines giving the space a severity absent from the rounded passages behind." },
  { id: "ps-g02", stretch: "st-square", req: [], line: "Small chisel marks cover the walls in close, even rows. Each scar is short and shallow, set beside the next with scarcely any untouched stone between them. The repetition makes the surface feel worked by increments rather than smoothed afterwards, thousands of little cuts preserving the method of the wall’s making without forming any separate picture." },
  { id: "ps-g03", stretch: "st-square", req: [], line: "The ceiling is flat—the only flat ceiling you have seen down here. It meets the walls at hard angles instead of flowing into them, turning the gallery into a long stone box. The difference changes your sense of height at once; there is a definite plane above you, level and measurable from one side to the other." },
  { id: "ps-g04", stretch: "st-square", req: [], line: "The square walls are bare except where the tally’s hand has cut into them. No other working interrupts the broad planes. The tally therefore sits with unusual clarity against the stone, each incision surrounded by enough emptiness to separate it from the next and to show exactly where that particular hand has passed." },
  { id: "ps-g05", stretch: "st-square", req: [], line: "Old hobnail impressions remain hardened in the dust of the square floor. Small round dents and angular edges repeat in partial soles, some overlapping, some isolated. The dust has compacted around them until the prints feel almost cast into the surface, preserving the pressure of boots even where loose powder has gathered thinly over the top." },
  { id: "ps-g06", stretch: "st-square", req: [], line: "Old smoke lingers in the gallery’s smell. It is faint, dry and stale, caught somewhere between the dust and the stone rather than floating sharply in the air. A deeper breath brings it out more clearly, a dark, ashy note that belongs to the square gallery and persists even where the air itself feels still." },
  { id: "ps-g07", stretch: "st-square", req: [], line: "At every ten paces, a short line is cut at the edge of the floor. Each mark sits close to the wall and lies across the direction of travel, small enough to step past without noticing. Once you find two, the regular interval makes the next one easy to anticipate along the straight gallery." },
  { id: "ps-g08", stretch: "st-square", req: [], line: "A square beam-slot has been cut into the wall. Its corners are exact and its depth disappears into shadow, but it is empty. No timber fills the opening now. The sharp-edged recess interrupts the chisel-marked surface with a dark geometric void, sized for something much thicker than a hand." },
  { id: "ps-g09", stretch: "st-square", req: [], line: "The square stone is darker than the rounded stone and crossed by cracks. Fine fractures run through the wall faces in branching lines, some stopping after a few inches, others continuing beyond the lamp’s strongest light. The darker colour makes their pale edges easier to see, giving this masonry a more broken surface than the smoother passages above." },
  { id: "ps-g10", stretch: "st-square", req: [], line: "The corners of the gallery are sharp enough to cut a finger. Wall, floor and ceiling meet without any softened transition, their edges holding narrow lines of shadow. You keep your hand away from the angles as you pass; even the smallest chipped place reveals how crisp the original corner remains." },
  { id: "ps-g11", stretch: "st-square", req: [], line: "A ceiling crack has been plugged with a wedge of wood gone grey. The timber is driven tightly into the fracture, its exposed end flattened nearly level with the stone. Age or dust has drained it of warmth, so only the grain distinguishes the plug from the darker ceiling around it." },
  { id: "ps-g12", stretch: "st-square", req: [], line: "A faint line of soot runs down the middle of the ceiling, left where lights were carried. It is narrowest directly overhead and broadens slightly where the stone surface roughens. The dark trace follows the gallery’s straight course with no turn or interruption, a smoky stripe suspended above the centre of the floor." },
  { id: "ps-g13", stretch: "st-square", req: [], line: "The floor rises almost imperceptibly towards the centre, like a road built to shed water. From wall to wall there is a shallow crown rather than a level plane. You feel it more readily through your ankles than you see it, one foot standing a fraction higher whenever you cross the gallery’s middle line." },
  { id: "ps-g14", stretch: "st-square", req: [], line: "Dust deepens as the gallery goes on. At first it only powders the stone, but farther ahead your boots press into a softer layer and leave clearer edges behind. The floor’s darker colour becomes progressively veiled, until the chisel-cut walls seem to rise from a pale, accumulating bed of fine grit." },
  { id: "ps-g15", stretch: "st-square", req: [], line: "A pale rectangle on the wall marks where a board once hung. The stone inside it is noticeably cleaner than the surrounding surface, its straight edges outlining the former shape. Four peg-holes remain, one near each corner, small dark points that fix the rectangle’s size even where the colour difference begins to fade." },
  { id: "ps-g16", stretch: "st-square", req: [], line: "Behind you the Stair is lit. Its nearest lamps still show through the opening as warm points descending out of sight. Ahead, the square gallery runs into darkness, its straight floor and walls visible only until the light weakens. Standing between them, you have ordered flame behind and an unlit geometric corridor before you." },
  { id: "ps-x01", stretch: "st-mouth", req: [], line: "From time to time a draught rises from below, strong enough to lift the dust. The fine layer on the floor loosens first at its edges, then swirls upward in pale threads around your boots. The air weakens again as quickly as it came, leaving the disturbed grains to drift back across the stone." }, // NOTE: 'Anywhere' in the source (no stretch); st-mouth is a placeholder
  { id: "ps-x02", stretch: "st-salt", req: [], line: "It is quiet enough here for each footfall to sound separate. Heel, sole and the faint scrape of grit arrive as distinct noises rather than merging into a continuous tread. The space between steps feels acoustically empty, so even a small shift of weight seems to belong to its own moment." }, // NOTE: 'Anywhere' in the source (no stretch); st-salt is a placeholder
  { id: "ps-x03", stretch: "st-hall", req: [], until: "b-3.A", line: "Far behind, the lamp’s light still touches the wall. It reaches only as a weak, warm patch now, too distant to show texture, but enough to keep one portion of stone from disappearing entirely. The rest of the passage between you and it has darkened into a long interval." }, // NOTE: 'Anywhere' in the source (no stretch); st-hall is a placeholder
  { id: "ps-x04", stretch: "st-hall", req: [], line: "Dust turns slowly in the beam of light and hangs there without settling. Individual grains drift upward, sideways, then back through the same narrow brightness, their movement so slight that some seem fixed in place. Outside the beam they vanish at once, leaving only the illuminated column full of suspended specks." }, // NOTE: 'Anywhere' in the source (no stretch); st-hall is a placeholder
  { id: "ps-m11", stretch: "st-mouth", req: [], line: "A maker’s stamp is pressed into the shaft brick, worn almost to a blur. Its shallow edges have softened until the impression seems rubbed into the clay rather than struck there. You can still distinguish the compressed patch from the surrounding brick, but whatever crispness the stamp once had has been thinned away by wear." },
  { id: "ps-m12", stretch: "st-mouth", req: [], line: "A bolt sits in the brickwork with a brown rust-stain running down beneath it. The stain begins tight around the metal and lengthens into a narrow taper across the brick below, darker near the bolt and weaker at its end. The iron itself is dulled and rough, its surface broken into small flakes of reddish brown." },
  { id: "ps-m13", stretch: "st-mouth", req: [], line: "Where the passage leaves the shaft, boots have scuffed the floor grey. The marks overlap until no single tread remains distinct, only a rubbed patch where the original surface has lost its colour. At the threshold your own sole crosses the same place, and the grey abrasion continues a little way into the passage before thinning out." },
  { id: "ps-m14", stretch: "st-mouth", req: [], line: "The passage is just wider than your reach. You stretch both arms until your shoulders pull tight, but you cannot quite touch both walls at once. One palm rests flat on stone while the fingers of the other hover short of the opposite side. The missing distance is small enough to make the passage feel measured against your body." },
  { id: "ps-h23", stretch: "st-hall", req: [], until: "b-3.A", line: "The lamp lays an oval of light across the floor, brightest near the ledge and softer at the edges. The stone within it shows its fine wear and shallow irregularities clearly. Beyond the oval, the hall is dark, so the visible floor seems briefly isolated, a pale island of stone surrounded by space the flame cannot describe." },
  { id: "ps-h24", stretch: "st-hall", req: [], line: "The wall beside the ledge is so densely cut that, at a distance, it resembles woven cloth. Grooves cross and crowd one another until the separate incisions merge into texture. Nearer the lamp, the illusion breaks apart again into stone and cuts, but from several paces back the worked surface has the tight, fibrous look of fabric." },
  { id: "ps-h25", stretch: "st-hall", req: [], line: "A hairline crack runs across the lip of one cup. It is narrow enough to vanish where the flame is weakest, then reappear as a fine dark thread along the stone edge. The fracture crosses the rim without widening, continuing from one side of the cup to the other while the hollow itself remains intact." },
  { id: "ps-h26", stretch: "st-hall", req: [], until: "b-3.A", line: "The hall floor feels cold even through your boots. The chill presses up through the soles after only a few moments standing still, sharper than the air around your ankles. Where your weight rests hardest, heel and forefoot seem to find the cold first, making the broad stone floor feel dense and deeply chilled beneath you." },
  { id: "ps-h27", stretch: "st-hall", req: [], line: "Two rings have been cut so close that their curves touch. At the meeting point there is no strip of untouched stone between them; one rounded groove reaches the other exactly. Their separate circles remain clear everywhere else, but here the pair is joined by a single contact, small enough to cover with a fingertip." },
  { id: "ps-h28", stretch: "st-hall", req: [], until: "b-3.A", line: "Somewhere beyond the lamp’s reach, the far wall returns your footsteps a moment late. Each tread sounds first beneath you, then comes back faintly from the darkness ahead, separated by just enough time to be heard as a second event. The delay gives the unseen end of the hall a distance that the lamp cannot show." },
  { id: "ps-h29", stretch: "st-hall", req: [], until: "b-3.A", line: "Near the lintel, the marks are cut deeper than elsewhere on the wall. Their grooves hold more darkness and their edges throw thicker shadows, making them stand out from the shallower work around them. The change is local: a dense patch of stronger cuts gathered close to the lintel, then diminishing again farther away." },
  { id: "ps-h30", stretch: "st-hall", req: ["b-3.A"], line: "The flames nearest the ledge lean, just perceptibly, towards it. The change is slight enough that you compare one with the next before trusting your eye. Farther along the wall the flames stand upright, but here their tips incline in the same direction, each bending a fraction towards the stone shelf." },
  { id: "ps-c21", stretch: "st-salt", req: [], line: "The salt floor lies in shallow ridges, like sand left by a tide. Each ridge is low and rounded, running only a short distance before fading into the next. Your boot crosses them one after another, rising and falling by scarcely more than a finger’s width over the hard, pale-grey surface." },
  { id: "ps-c22", stretch: "st-salt", req: [], line: "A fist-sized lump of salt has fallen from the roof and remains where it struck the floor. Its broken faces are brighter than the older surface around it, and a small scatter of grains lies close by. The piece sits awkwardly on one edge, dense and chalky, directly beneath the rough place from which it came." },
  { id: "ps-c23", stretch: "st-salt", req: [], line: "The strip of cut stone carrying the tally stands a hand’s width proud of the surrounding salt. Its face projects cleanly from the softer-looking mineral on either side, making the marks easier to follow. Seen end-on, the difference in depth is unmistakable: a narrow stone spine set forward from the salt wall by the width of your palm." },
  { id: "ps-c24", stretch: "st-salt", req: [], line: "The gallery air is drier than the hall’s. Moisture leaves your lips quickly, and each breath feels thin against the mouth. Salt sits on your tongue without your having touched the wall, a faint mineral taste that gathers as you remain among the grey and white faces." },
  { id: "ps-c25", stretch: "st-salt", req: [], line: "The tally rounds a corner of the wall without breaking its line. The marks approach the angle, tighten across the turn, then continue along the next face at the same height. From either side you can see part of the sequence vanish around the edge, its continuity preserved through the change in direction." },
  { id: "ps-c26", stretch: "st-salt", req: [], line: "Faint pencil ticks sit beside some marks in the tally’s first stretch. They are thinner and greyer than the cuts, resting on the surface rather than entering it. Not every mark has one. Where they do appear, the pencil strokes sit close to the incisions, small enough that the salt’s grain nearly overwhelms them." },
  { id: "ps-c27", stretch: "st-salt", req: [], line: "A darker grey vein crosses the salt face on a slant. It begins low on one side and rises steadily across the wall, cutting through the paler horizontal bands without following them. The vein is narrow but persistent, its colour dense enough to remain visible even where the surface is roughened by old tool marks." },
  { id: "ps-c28", stretch: "st-salt", req: [], line: "A boot-heel has left a hollow in the salt floor, with another close beside it. Each depression is rounded at the back and shallower towards the front, pressed into the hard surface rather than scratched across it. The pair sits near enough together to read as two separate heels, their edges softened by loose grains." },
  { id: "ps-c29", stretch: "st-salt", req: [], line: "Fine salt grains have gathered in a little heap where the split meets the floor. The pile is no higher than a knuckle, brightest at its loose edges and darker where grains are compacted against the stone. A few crystals have rolled away from it, making a sparse trail across the harder floor." },
  { id: "ps-c30", stretch: "st-salt", req: [], line: "Every visible cut of the tally is the same depth, from first to last. Near the beginning and far along the wall, each incision holds an equal measure of shadow. The constancy is easiest to see where the light runs sideways across them: no mark stands deeper, shallower, heavier or fainter than the next." },
  { id: "ps-s13", stretch: "st-camp", req: [], line: "A mug sits on the floor by the cot. A dry brown ring remains at the bottom, thin at one side and thicker at the other where the last liquid settled. The inside of the cup is otherwise empty, and the stain has dried to a dull edge around the pale base." },
  { id: "ps-s14", stretch: "st-camp", req: [], line: "The camp doorway is round-topped, its arch following the chamber’s softened geometry. A jacket hangs from a crack in it, caught by part of the fabric rather than by a hook. One sleeve falls lower than the other, and the weight of the coat pulls a narrow fold tight against the stone." },
  { id: "ps-s15", stretch: "st-camp", req: [], line: "Sheets of paper are everywhere, each held down by a small stone. Some lie singly; others overlap in loose spreads across the available surfaces. The stones differ in size but serve the same purpose, pressing corners and edges flat so that no page lifts in the moving air from the doorway." },
  { id: "ps-s16", stretch: "st-camp", req: [], line: "The washing-up bowl is dry. A pale residue marks the inner curve where water once sat, but no moisture remains when you look into it. The sponge inside has hardened, its corners stiff and its porous surface drawn tight. It rests on one side of the basin without yielding under its own weight." },
  { id: "ps-s17", stretch: "st-camp", req: [], line: "A rolled mat leans against the wall with its strap hanging open. The roll has loosened just enough for the outer edge to lift away from the layers beneath. Its unfastened strap drops alongside it, buckle low to the floor, leaving the mat held closed only by the stiffness of its own curl." },
  { id: "ps-s18", stretch: "st-camp", req: [], line: "FOOD is written on a cardboard box in thick, practical letters. Underneath, smaller: *mostly*. The second word sits close enough to belong to the first, but its reduced size changes the whole label. The cardboard is creased at the corners, and both inscriptions remain plainly visible on the broad side facing the room." },
  { id: "ps-s19", stretch: "st-camp", req: [], line: "A plastic water bottle stands one-third full. The water is flat and clear, without bubbles clinging to the sides or any movement on the surface. The bottle walls flex inward slightly where the plastic has been squeezed before, but the remaining water sits level in the bottom third." },
  { id: "ps-s20", stretch: "st-camp", req: [], line: "At the doorway, the smell of her camp thins and the stone smell returns. Paraffin and paper fade within a pace, replaced by the dry mineral air of the passage. Standing on the threshold gives you both at once for a moment: the human, stored scent behind you and bare stone immediately ahead." },
  { id: "ps-t21", stretch: "st-stair", req: [], line: "The stair lamps are set at the height of a tall man’s hand. Their cups repeat along the wall just above the level your own relaxed hand would naturally reach. As the steps descend, the lamps descend with them, preserving that relation to the body from one section of the flight to the next." },
  { id: "ps-t22", stretch: "st-stair", req: [], line: "A long crack follows one side of the flight, running beside the steps through riser after riser. It narrows and widens but never leaves that edge. Yet none of the steps has shifted: the treads remain level with one another, their worn centres aligned despite the fracture travelling alongside them." },
  { id: "ps-t23", stretch: "st-stair", req: [], line: "Use has rounded the edges of the steps; none is sharp now. Every lip has been softened into a slight curve, most noticeably in the middle where feet pass. At the outer ends the stone keeps a little more of its original angle, but even there the corners have lost any cutting edge." },
  { id: "ps-t24", stretch: "st-stair", req: [], line: "Looking down from the landing, the lamps form a line that bends with the Stair at the turn. The upper flames descend straight, gather at the corner, then continue away along the next flight. Their positions make the change of direction legible from above before the lower treads themselves can all be seen." },
  { id: "ps-t25", stretch: "st-stair", req: [], line: "A ring is cut low into the face of one step, half erased by passing feet. Its upper curve remains clear in the riser, but the lower part has been rubbed shallow where soles repeatedly crossed the edge. What survives is enough to show the full round shape, interrupted by wear rather than by the original cut." },
  { id: "ps-g17", stretch: "st-square", req: [], line: "Among the even pick-marks, one cut is deeper: a blow that went wrong. It bites farther into the square wall than the surrounding strokes and breaks their regular surface with a single dark notch. The rows continue around it at their usual depth, making that one misplaced force easy to pick out." },
  { id: "ps-g18", stretch: "st-square", req: [], line: "The square floor has been swept once. A clean strip follows one wall, narrow and continuous, while dust remains thicker across the rest of the gallery. The swept edge is not perfectly straight; little tongues of powder intrude into it, but the cleared path keeps close to the wall for as far as the lamp shows." },
  { id: "ps-g19", stretch: "st-square", req: [], line: "A grey stub of candle-grease rests on the lip of a crack. It is no longer shaped like a candle, only a squat piece of hardened wax flattened slightly where it meets the stone. Its colour nearly matches the wall, though the smoother surface catches a dull sheen that the fractured rock beside it does not." },
  { id: "ps-g20", stretch: "st-square", req: [], line: "The gallery walls lean inward very slightly as they rise. At floor level they are farther apart than at the flat ceiling, though the difference is small enough to miss at first. Once seen, the taper persists along the entire visible length, turning the square passage into a subtly narrowing shape from bottom to top." },
  { id: "ps-g21", stretch: "st-square", req: [], line: "Two chisel cuts cross each other on the square wall. No others do. One short stroke runs through the other at an angle, making a tiny intersection among rows that otherwise remain separate. Because every neighbouring cut keeps its own space, the crossed pair draws the eye despite being no larger than the marks around it." },
];

/** The four 'Anywhere' lines (ps-x…): the source gives them no stretch; the stretch on each is a placeholder. At most once a day (§9.9). */
export const anywherePassages: string[] = ['ps-x01', 'ps-x02', 'ps-x03', 'ps-x04'];
